function updateEqSim() {
    const x = parseInt(document.getElementById('input-eq-x').value, 10);
    document.getElementById('badge-eq-x').innerText = 'x = ' + x;

    const lhs = 2 * x + 5;
    const rhs = 17 - x;

    document.getElementById('lhs-val').innerText = lhs;
    document.getElementById('rhs-val').innerText = rhs;
    document.getElementById('lhs-calc').innerText = `2(${x}) + 5 = ${lhs}`;
    document.getElementById('rhs-calc').innerText = `17 - ${x} = ${rhs}`;

    const banner = document.getElementById('truth-banner');
    const icon = document.getElementById('truth-icon');
    const status = document.getElementById('truth-status');
    const desc = document.getElementById('truth-desc');

    if (lhs === rhs) {
        banner.style.background = 'rgba(16, 185, 129, 0.15)';
        banner.style.border = '2px solid #10b981';
        icon.innerHTML = '<i class="fas fa-check-circle" style="color:#10b981;"></i>';
        status.innerText = 'TRUE STATEMENT!';
        status.style.color = '#10b981';
        desc.innerText = `${lhs} = ${rhs} ➡ x = ${x} IS in the solution set: {${x}}`;
    } else {
        banner.style.background = 'rgba(225, 29, 72, 0.15)';
        banner.style.border = '2px solid #f43f5e';
        icon.innerHTML = '<i class="fas fa-times-circle" style="color:#f43f5e;"></i>';
        status.innerText = 'FALSE STATEMENT';
        status.style.color = '#f43f5e';
        desc.innerText = `${lhs} ≠ ${rhs} ➡ x = ${x} is NOT in the solution set`;
    }
}

function setEqX(val) {
    document.getElementById('input-eq-x').value = val;
    updateEqSim();
}

document.addEventListener('DOMContentLoaded', () => {
    updateEqSim();
});
